import{_ as e,o as l,c as o,a5 as u}from"./chunks/framework.DJo0M80U.js";const r=JSON.parse('{"title":"v-model双向绑定的原理","description":"简介 v model 是 Vue 中用于双向数据绑定的指令。它不仅可以应用于表单元素，也可以应用于自定义组件。本文将详细说明 v model 在表单元素和自定义组件中的使用。 在表单元素中的使用 输入框 (input) \\\\<template\\\\ \\\\<div\\\\ \\\\<input v m。","frontmatter":{"title":"v-model双向绑定的原理","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","模板、组件与交互"],"description":"简介 v model 是 Vue 中用于双向数据绑定的指令。它不仅可以应用于表单元素，也可以应用于自定义组件。本文将详细说明 v model 在表单元素和自定义组件中的使用。 在表单元素中的使用 输入框 (input) \\\\<template\\\\ \\\\<div\\\\ \\\\<input v m。","sidebarWeight":51,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/api/表单双向绑定/v-model双向绑定的原理.md"},"headers":[],"relativePath":"posts/Vue系统教程/02-模板、组件与交互/表单双向绑定/v-model双向绑定的原理.md","filePath":"posts/Vue系统教程/02-模板、组件与交互/表单双向绑定/v-model双向绑定的原理.md"}'),p={name:"posts/Vue系统教程/02-模板、组件与交互/表单双向绑定/v-model双向绑定的原理.md"};function d(a,t,s,i,g,m){return l(),o("div",null,[...t[0]||(t[0]=[u('<div><h1 id="v-model双向绑定的原理" tabindex="-1">v-model双向绑定的原理 <a class="header-anchor" href="#v-model双向绑定的原理" aria-label="Permalink to &quot;v-model双向绑定的原理&quot;">​</a></h1><blockquote><p>本节目标：理解“v-model双向绑定的原理”的核心思路，并能把它用于实际开发或面试表达。 简介 <code>v-model</code> 是 Vue 中用于双向数据绑定的指令。它不仅可以应用于表单元素，也可以应用于自定义组件。本文将详细说明 <code>v-model</code> 在表单元素和自定义组件中的使用。 在表单元素中的使用 输入框 (input) &lt;template&gt; &lt;div&gt; &lt;input v-model=&quot;message&quot; placeholder=&quot;Type something&quot;&gt; &lt;p&gt;Message is: {{ message }}&lt;/p&gt; &lt;/div&gt; &lt;/template&gt; &lt;script&gt; export default { data() { return { message: &#39;&#39; }; } }; &lt;/script&gt; 在这个例子中，<code>v-model</code> 绑定了一个输入框和一个数据属性 <code>message</code>。当用户在输入框中输入时，<code>message</code> 会自动更新，反之亦然。 复选框 (checkbox) &lt;template&gt; &lt;div&gt; &lt;input type=&quot;checkbox&quot; v-model=&quot;checked&quot;&gt; &lt;p&gt;Checked: {{ checked }}&lt;/p&gt; &lt;/div&gt; &lt;/template&gt; &lt;script&gt; export default { data() { return { checked: false }; } }; &lt;/script&gt; 单选框 (radio) &lt;template&gt; &lt;div&gt; &lt;input type=&quot;radio&quot; value=&quot;Option1&quot; v-model=&quot;picked&quot;&gt; Option 1 &lt;input type=&quot;radio&quot; value=&quot;Option2&quot; v-model=&quot;picked&quot;&gt; Option 2 &lt;p&gt;Picked: {{ picked }}&lt;/p&gt; &lt;/div&gt; &lt;/template&gt; &lt;script&gt; export default { data() { return { picked: &#39;&#39; }; } }; &lt;/script&gt; 选择框 (select) &lt;template&gt; &lt;div&gt; &lt;select v-model=&quot;selected&quot;&gt; &lt;option disabled value=&quot;&quot;&gt;Please select one&lt;/option&gt; &lt;option&gt;A&lt;/option&gt; &lt;option&gt;B&lt;/option&gt; &lt;option&gt;C&lt;/option&gt; &lt;/select&gt; &lt;p&gt;Selected: {{ selected }}&lt;/p&gt; &lt;/div&gt; &lt;/template&gt; &lt;script&gt; export default { data() { return { selected: &#39;&#39; }; } }; &lt;/script&gt; 在自定义组件中的使用 Vue 2 中自定义组件的 v-model 在 Vue 2 中，自定义组件默认使用 <code>value</code> 作为 prop，<code>input</code> 作为事件。 &lt;!-- CustomInput.vue --&gt; &lt;template&gt; &lt;input :value=&quot;value&quot; @input=&quot;$emit(&#39;input&#39;, $event.target.value)&quot;&gt; &lt;/template&gt; &lt;script&gt; export default { props: [&#39;value&#39;] }; &lt;/script&gt; 在父组件中使用： &lt;template&gt; &lt;div&gt; &lt;CustomInput v-model=&quot;message&quot;&gt;&lt;/CustomInput&gt; &lt;p&gt;Message is: {{ message }}&lt;/p&gt; &lt;/div&gt; &lt;/template&gt; &lt;script&gt; import CustomInput from &#39;./CustomInput.vue&#39;; export default { components: { CustomInput }, data() { return { message: &#39;&#39; }; } }; &lt;/script&gt; Vue 3 中自定义组件的 v-model 在 Vue 3 中，自定义组件默认使用 <code>modelValue</code> 作为 prop，<code>update:modelValue</code> 作为事件。 &lt;!-- CustomInput.vue --&gt; &lt;template&gt; &lt;input :value=&quot;modelValue&quot; @input=&quot;$emit(&#39;update:modelValue&#39;, $event.target.value)&quot;&gt; &lt;/template&gt; &lt;script&gt; export default { props: [&#39;modelValue&#39;] }; &lt;/script&gt; 在父组件中使用： &lt;template&gt; &lt;div&gt; &lt;CustomInput v-model=&quot;message&quot;&gt;&lt;/CustomInput&gt; &lt;p&gt;Message is: {{ message }}&lt;/p&gt; &lt;/div&gt; &lt;/template&gt; &lt;script&gt; import CustomInput from &#39;./CustomInput.vue&#39;; export default { components: { CustomInput }, data() { return { message: &#39;&#39; }; } }; &lt;/script&gt; 自定义 v-model 的属性和事件 在 Vue 3 中，你可以通过传递参数来自定义 <code>v-model</code> 的 prop 和事件名称。例如，使用 <code>v-model:title</code> 来绑定 <code>title</code> prop，并监听 <code>update:title</code> 事件： &lt;!-- CustomInput.vue --&gt; &lt;template&gt; &lt;input :value=&quot;title&quot; @input=&quot;$emit(&#39;update:title&#39;, $event.target.value)&quot;&gt; &lt;/template&gt; &lt;script&gt; export default { props: [&#39;title&#39;] }; &lt;/script&gt; 在父组件中使用： &lt;template&gt; &lt;div&gt; &lt;CustomInput v-model:title=&quot;title&quot;&gt;&lt;/CustomInput&gt; &lt;p&gt;Title is: {{ title }}&lt;/p&gt; &lt;/div&gt; &lt;/template&gt; &lt;script&gt; import CustomInput from &#39;./CustomInput.vue&#39;; export default { components: { CustomInput }, data() { return { title: &#39;&#39; }; } }; &lt;/script&gt; 结论 <code>v-model</code> 是 Vue 中实现双向数据绑定的强大工具，不仅可以用于表单元素，也可以用于自定义组件。通过了解其在 Vue 2 和 Vue 3 中的不同实现方式，可以更加灵活地使用 <code>v-model</code> 来满足各种开发需求。</p></blockquote></div>',1)])])}const n=e(p,[["render",d]]);export{r as __pageData,n as default};
